"""Explain fallback context, directional fences, stronger primitives and defined checks."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1601': ('빈칸이 있는 조리법에 재료 이름을 넣으면 비슷한 요리를 만들 수 있어요. 코드 템플릿도 타입과 함수 이름을 빈칸에 넣어 여러 계열의 C 코드를 만들어요.', '문맥 변수로 같은 템플릿을 재사용하는 방법을 이해합니다.', 'inc 양식에 atomic을 넣으면 raw_atomic_add(1, v), atomic64를 넣으면 raw_atomic64_add(1, v)가 된다고 적으세요.', ['템플릿은 공통 모양을 적어 놓고 일부를 변수로 채우는 양식이에요. gen_template_fallback은 이 양식을 읽기 전에 필요한 정보를 local 변수로 준비해요. local은 해당 함수의 변수라는 뜻이에요.', 'meta는 반환 종류, pfx·name·sfx는 이름 조각, order는 순서 이름이에요. atomic은 원자 계열 이름, int는 기본 정수 타입 이름을 담아요. 여기의 int는 쉘 변수 이름이지 이 순간 C 정수를 계산하는 명령이 아니에요.', '공통 도우미로 반환 타입 ret, 반환 문구 retstmt, 선언 목록 params, 호출 목록 args를 만들어요. 같은 양식도 이 값들에 따라 다른 C 글자가 돼요.', '마지막 . ${template}는 준비한 쉘 문맥에서 양식 파일을 실행해요. 그래서 양식이 atomic이나 order 같은 변수에 접근해 글자를 출력할 수 있어요. 별도 C 함수 호출과는 다른 단계예요.', 'inc 양식은 1을 더하는 raw add 호출을 출력해요. 반환 없는 기본 atomic 형태라면 raw_atomic_add(1, v), atomic64 형태라면 raw_atomic64_add(1, v)가 돼요. 반환·순서 형태가 있으면 그 이름 조각도 함께 붙어요.', '생성 중 자료 구조가 서로 바뀌거나 실제 counter가 증가하는 것은 아니에요. 공통 규칙에서 다른 C 텍스트를 만드는 것이에요. 실제 증가와 순서 보장은 그 코드가 나중에 컴파일되어 호출될 때의 구현을 봐야 해요.'], [('같은 템플릿으로 atomic와 atomic64 코드를 만들 수 있는 이유는 무엇인가요?', ['실행 중 두 자료 구조가 자동으로 서로 변해서예요', '타입·이름·인자를 변수로 준비해 양식에 넣기 때문이에요'], '정답은 두 번째예요. 같은 빈칸에 atomic 또는 atomic64를 넣으면 다른 함수 이름을 출력할 수 있어요. 생성 시간의 글자 조합과 실행 중 자료 변환은 달라요.'), ('템플릿을 source하는 순간 커널 counter를 실제로 1 증가시키나요?', ['아니요. 나중에 실행할 C 코드의 글자를 출력해요', '네. 모든 커널 counter를 즉시 증가시켜요'], '정답은 첫 번째예요. source는 현재 쉘에서 양식의 명령을 수행해 코드를 출력해요. 그 C가 실제로 호출되는 시점과 구별하세요.')]), 'os1602': ('한 묶음으로 숫자를 고치는 도구는 있는데 주변 작업의 순서 약속이 부족할 수 있어요. 그때 앞이나 뒤에 필요한 순서 장치를 더하는 방법을 살펴봐요.', 'relaxed 원자 연산과 순서 fence의 역할·위치를 구별합니다.', 'acquire: 연산 → 뒤 장벽, release: 앞 장벽 → 연산, full: 앞 장벽 → 연산 → 뒤 장벽을 그리세요.', ['relaxed 원자 연산도 대상 숫자의 원자성은 지켜요. 다만 다른 주소의 메모리 접근 순서에 추가 약속이 없어요. fence는 이런 순서를 보강하는 장벽을 뜻해요.', '같은 기본 이름의 arch relaxed 연산이 있으면 생성기는 순서 양식을 이용할 수 있어요. _acquire에서 앞 밑줄을 떼 acquire 양식을 고르고, 순서 이름이 비면 fence라는 full 보강 양식을 골라요.', 'acquire 양식은 relaxed 연산을 먼저 호출해 결과를 ret에 담고, __atomic_acquire_fence를 호출한 뒤 ret를 반환해요. 뒤 장벽을 실행하기 전에 바로 반환해 버리지 않으려고 결과를 잠시 보관해요.', 'release 양식은 __atomic_release_fence를 먼저 호출하고 그다음 relaxed 연산을 해요. 앞선 접근의 순서를 보강하는 방향이라 장벽 위치가 acquire 양식과 달라요.', 'full 양식은 __atomic_pre_full_fence, relaxed 연산, __atomic_post_full_fence 순서예요. 그 뒤 결과를 반환해요. 앞뒤 접근을 묶을 필요한 장벽은 실제 아키텍처 구현의 정의를 따라 동작해요.', '기반 RMW가 제공하는 원자성과 추가 장벽의 순서 보장을 나누어 보세요. 평범한 읽기와 쓰기를 따로 한 뒤 장벽을 붙인다고 갑자기 하나의 원자적 RMW가 되는 것은 아니에요. 여기서는 출력 코드의 배치를 확인하며 모든 CPU의 실제 순서를 실험한 것은 아니에요.'], [('acquire 보강 양식에서 장벽은 어디에 있나요?', ['relaxed 연산 앞에 release 장벽을 둬요', 'relaxed 연산의 결과를 얻은 뒤에 둬요'], '정답은 두 번째예요. ret에 결과를 담고 __atomic_acquire_fence를 거쳐 반환해요. release 양식의 앞 장벽과 혼동하지 마세요.'), ('full 보강 양식은 어떤 순서인가요?', ['앞 full 장벽 → relaxed 원자 연산 → 뒤 full 장벽이에요', '일반 읽기와 쓰기를 각각 한 번 하고 원자적이라고 부르면 돼요'], '정답은 첫 번째예요. 원자성은 이미 원자적인 기반 연산에서 얻고 장벽으로 주변 순서를 보강해요. 장벽만으로 분리된 일반 읽기·쓰기가 원자 연산이 되지는 않아요.')]), 'os1603': ('앞뒤 순서를 모두 지키는 도구로 한쪽 순서만 필요한 작업을 할 수도 있어요. 하지만 지금 도구가 더 강하다고 다른 환경에서도 그 추가 약속을 기대하면 안 돼요.', '강한 full 구현 재사용과 공개 API의 최소 약속을 구별합니다.', 'relaxed 기반: 추가 장벽으로 보강, full 기반: 이미 강한 연산을 직접 호출의 두 줄을 적으세요.', ['원하는 _acquire·_release·_relaxed 형태가 직접 없어도 같은 기본 연산의 full 구현이 있으면 필요한 약속을 충족할 수 있어요. full은 원자 연산 앞뒤 접근에 대해 더 강한 순서 규칙을 제공해요.', '생성기는 순서 꼬리표가 있고 기본형이 implicitly relaxed 분류가 아닌지 확인해요. implicitly relaxed는 별도 꼬리표 없이도 기본이 relaxed인 v·l·s 같은 분류예요. 이 기본형들을 full이라고 잘못 가정하지 않기 위한 조건이에요.', '조건에 맞는 경로에서는 arch의 기본 full 함수를 그대로 호출하는 코드를 출력해요. 예를 들어 add_return_acquire를 필요한 순서를 이미 갖춘 기본 add_return에 연결할 수 있어요.', '이것은 relaxed 기반 연산 앞뒤에 장벽을 붙이는 경로와 달라요. full 기반은 그 연산 자체가 강한 약속을 갖기 때문에 해당 직접 전달 코드에 별도 acquire fence가 보이지 않을 수 있어요.', '그러므로 추가 fence 호출이 없다고 순서 보장도 없다고 판단하면 안 돼요. 선택된 기반 함수의 약속까지 읽어야 해요. 전체 호출 흐름에서 누가 필요한 순서를 제공하는지 찾아보세요.', '반대로 호출자는 공개된 _acquire나 _relaxed의 약속만을 기준으로 코드를 작성해야 해요. 지금 기계에서 우연히 full로 구현됐다는 추가 강도에 기대면 다른 기계의 구현에서 깨질 수 있어요. 더 강하게 구현할 수 있다는 것과 더 강한 약속을 요구해도 된다는 것은 달라요.'], [('기본 full backend를 acquire 형태의 구현에 재사용할 수 있나요?', ['아니요. 이름이 다르면 재사용은 불가능해요', '네. 필요한 순서보다 강한 구현으로 약속을 충족할 수 있어요'], '정답은 두 번째예요. 생성기는 조건에 맞을 때 기본 arch 연산을 직접 호출해요. 단, 기본형이 실제로 full인 분류인지 확인해야 해요.'), ('직접 전달 코드에 acquire fence가 따로 없으면 acquire 약속도 없나요?', ['아니요. 선택한 full 기반 연산이 필요한 순서를 제공해요', '네. 눈에 보이는 추가 장벽 개수만으로 판단하면 돼요'], '정답은 첫 번째예요. 기반 연산 자체의 보장도 함께 봐야 해요. relaxed 보강 경로와 full 재사용 경로는 필요한 약속을 마련하는 방법이 달라요.')]), 'os1604': ('이름이 명단에 적혔는지 확인하는 도구가 건물 안의 모든 사람까지 찾아 주지는 않아요. 전처리 이름 검사와 C 함수가 실제로 제공되는지의 확인도 서로 달라요.', 'defined의 검사 범위와 필수 기반 연산의 필요성을 이해합니다.', '전처리 매크로 이름 → defined 검사, C 함수 선언·정의 → 컴파일·연결 확인의 두 칸을 그리세요.', ['#if defined(arch_name)은 arch_name이라는 전처리 매크로가 정의됐는지 검사해요. C 함수의 선언과 구현을 모두 검색하는 도구가 아니에요. 같은 철자의 함수가 있어도 매크로가 없으면 이 검사는 그것을 알아내지 못해요.', '원문 주석은 아키텍처가 전처리 심볼 없이 C 함수로 연산을 제공할 수 있다고 설명해요. 그래서 단순히 defined가 거짓이라는 이유만으로 필요한 함수도 없다고 단정할 수 없어요.', '생성기는 대체 양식이 없고 기본 순서이며 relaxed 변형도 없는 경우를 따로 다뤄요. 이 경우 arch 함수를 직접 호출하는 코드를 출력하고 해당 함수 생성을 마쳐요. 아키텍처가 필수로 제공해야 하는 기반 연산의 경로예요.', '이 직접 호출이 없는 기능을 새로 만들어 주는 것은 아니에요. 실제 아키텍처 코드에 필요한 연산이 있어야 해요. 빠졌다면 컴파일이나 연결 과정에서 실제 문맥에 맞는 진단을 확인해야 해요.', '다른 선택 경로에서도 직접·순서 보강·템플릿 모두 마련할 수 없으면 생성된 #error로 오류를 표시하는 경우가 있어요. fallback이라는 이름이 모든 누락을 자동 해결한다는 뜻은 아니에요.', '따라서 매크로 정의, C 선언, C 구현과 지원 설정을 함께 확인하세요. 평범한 대입으로 아무 원자 연산이나 대신할 수도 없어요. 대체 구현은 필요한 기반 연산을 이용해 원자성과 순서 약속을 지키는 구성이어야 해요.'], [('defined(arch_name)은 C 함수 선언이 있는지도 자동으로 찾아 주나요?', ['네. 컴파일러의 모든 함수 정보를 검색해요', '아니요. 전처리 매크로 이름이 정의됐는지 검사해요'], '정답은 두 번째예요. 전처리 단계의 이름 검사와 C 함수 제공 여부는 다른 수준이에요. 원문 주석도 매크로 없는 C 함수가 있을 수 있다고 설명해요.'), ('기반 연산이 하나도 없어도 모든 원자 API가 자동으로 만들어지나요?', ['아니요. 반드시 제공해야 할 기반 연산과 지원 조건이 있어요', '네. 부족한 부분은 모두 일반 대입으로 대체돼요'], '정답은 첫 번째예요. 생성기는 제공된 도구를 조합해 코드를 만들어요. 일반 대입으로 모든 원자성과 순서 보장을 대신할 수는 없어요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_396.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
